arguments.new_str:
using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change 1: Discriminator property renamed from "Discriminator" to "$type" in EF Core 9.
        // Preserve the old property name so existing documents remain readable.
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // Breaking change 2: Id format changed from "EntityType|KeyValue" to just "KeyValue" in EF Core 9.
        // Preserve the old id format so existing documents are found by their original ids.
        modelBuilder.Entity<Blog>().HasIdProperty(b => b.Id, true);

        // Breaking change 3: Cosmos DB provider no longer supports client-side indexes (HasIndex).
        // Indexes must be configured through the Azure Portal / IaC on the Cosmos container.
        // Removed: modelBuilder.Entity<Blog>().HasIndex(b => b.Name);
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; } }

