        context.SaveChanges();
    }
}

arguments.new_str:
class SyncJob
{
    void Run(BlogContext context)
    {
        var blogs = context.Blogs.ToList();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }

        // Breaking change 4: EF Core 9 Cosmos provider uses patch API (partial update) by default
        // instead of replacing the full document. This is generally fine, but be aware that
        // only tracked property changes are sent. Use full-document replace if needed:
        // context.Database.AutoTransactionBehavior = AutoTransactionBehavior.Never; // already default
        context.SaveChanges();
    }
}

